def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for c in range(1, w - 1):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            candidates.append((abs(c - (w - 1) / 2), 'col', c))
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            candidates.append((abs(r - (h - 1) / 2), 'row', r))
    _, orient, cut = min(candidates)
    if orient == 'col':
        a = [row[:cut] for row in grid]
        b = [row[cut + 1:] for row in grid]
    else:
        a, b = grid[:cut], grid[cut + 1:]
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    color = max(shared, key=lambda v: sum(x == v for row in a for x in row) + sum(x == v for row in b for x in row))
    oh, ow = min(len(a), len(b)), min(len(a[0]), len(b[0]))
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(ow)] for r in range(oh)]
